pub fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    debug_assert!(!a.is_empty(), "input vectors must be non-empty");
    debug_assert_eq!(a.len(), b.len(), "input vectors must have identical length");

    // Zip pairs corresponding elements and XOR them.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x ^ y)
        .collect()
}

